'use strict';
(() => {
 const key='rahyar.mapMarks.v1';let marks=[],markers=[],mode=null,bound=false,avoidRows=[];try{avoidRows=JSON.parse(localStorage.getItem('rahyar.routeAvoids.v1')||'[]');}catch{}
 try{marks=JSON.parse(localStorage.getItem(key)||'[]').filter(p=>window.RahyarTripModel.validPoint(p.coord));}catch{}
 const text=(tag,value)=>{const e=document.createElement(tag);e.textContent=value;return e;};
 function navigate(place){if(watch!==null&&!confirm('Replace your current destination and recalculate with your current vehicle restrictions?'))return;setSearchedDestination(place,true);}
 function draw(){markers.forEach(m=>m.remove());markers=[];for(const place of marks){if(navigationMap){const b=text('button',(place.favorite?'★ ':'◆ ')+place.name);b.className='map-mark-action';b.title=place.name;b.onclick=e=>{e.stopPropagation();popup(place.coord,place);};markers.push(new maplibregl.Marker({element:b}).setLngLat(place.coord).addTo(navigationMap));b.setAttribute('aria-label','Saved place '+place.name);}if(map){const m=L.marker([place.coord[1],place.coord[0]]).addTo(map);m.bindTooltip(place.name);m.on('click',()=>popup(place.coord,place));markers.push(m);}}}
 function popup(coord,existing){const box=document.createElement('div'),input=document.createElement('input');input.value=existing?.name||'Map place';let typed=false;input.addEventListener('input',()=>{typed=true;});input.maxLength=80;input.setAttribute('aria-label','Place label');box.append(input);const save=text('button','Save label / favorite');save.className='map-mark-action';save.onclick=()=>{const place={id:existing?.id||crypto.randomUUID(),name:input.value.trim()||'Map place',en:input.value.trim()||'Map place',coord,favorite:true,mapPin:true,addressLabel:input.value.trim()||'Map place'};marks=[place,...marks.filter(p=>p.id!==place.id)];try{localStorage.setItem(key,JSON.stringify(marks));draw();message('Map label saved on this device.');}catch{message('Could not save this place. Device storage unavailable.',true);}};const go=text('button','Navigate here');go.className='map-mark-action';go.onclick=()=>{navigate({...existing,name:input.value||'Map destination',coord,mapPin:true});};const avoid=(reason)=>{avoidRows=[{coord,reason,expires:Date.now()+86400000},...avoidRows.filter(p=>Date.now()<p.expires)].slice(0,12);localStorage.setItem('rahyar.routeAvoids.v1',JSON.stringify(avoidRows));message('Driver road avoidance saved (not official data). Recalculating with vehicle restrictions…');if(lastPos&&watch!==null){const captured=session;let tries=0;const retry=()=>{if(captured!==session||++tries>30)return;if(routeBusy){setTimeout(retry,1000);return;}calculate(lastPos,session,gpsTravelHeading);};retry();}};const closed=text('button','Avoid: road closed');closed.className='map-mark-action';closed.onclick=()=>avoid('closed');const truck=text('button','Avoid: truck prohibited');truck.className='map-mark-action';truck.onclick=()=>avoid('truck');box.append(save,go,closed,truck);if(navigationReady)new maplibregl.Popup().setLngLat(coord).setDOMContent(box).addTo(navigationMap);else L.popup().setLatLng([coord[1],coord[0]]).setContent(box).openOn(map);findMapPinAddress(coord).then(address=>{if(address&&!existing&&!typed){input.value=address.label;}}).catch(()=>{});}
 function start(next='mark'){mode=next;message('Tap a place on the map to label it, save a favorite, or navigate.');}
 function bind(){if(bound||!map)return;bound=true;for(const host of [$('navigation-map'),$('map')].filter(Boolean))host.addEventListener('click',event=>{if(!mode)return;const rect=host.getBoundingClientRect(),point=[event.clientX-rect.left,event.clientY-rect.top],p=host.id==='navigation-map'?navigationMap.unproject(point):map.containerPointToLatLng(point);event.preventDefault();event.stopImmediatePropagation();mode=null;popup([p.lng,p.lat]);},true);draw();}
 function list(){const d=document.createElement('dialog');d.className='nav-feature-dialog';d.append(text('h2','Saved addresses & map labels'));const close=text('button','Close');close.onclick=()=>d.close();d.append(close);for(const p of [...savedPlaces.map(x=>({...x.place,name:x.label})),...marks]){const b=text('button',p.name||p.addressLabel);b.className='map-mark-action';b.onclick=()=>{d.close();navigate(p);};d.append(b);}if(!d.children.length)d.append(text('p','No saved places.'));document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
 window.RahyarMapPlaces={start,list,draw,avoids:vehicle=>avoidRows.filter(p=>Date.now()<p.expires&&(p.reason!=='truck'||vehicle==='truck'))};const timer=setInterval(()=>{bind();if(bound)clearInterval(timer);},500);
})();
